#include "crashpad/page.h"
#include <string.h>

uint32_t cp_crc32c(const void *data,size_t n,uint32_t seed){const uint8_t*p=data;uint32_t c=~seed;for(size_t i=0;i<n;i++){c^=p[i];for(unsigned b=0;b<8;b++)c=(c>>1)^((uint32_t)-(int32_t)(c&1u)&0x82f63b78u);}return ~c;}
void cp_page_seal(cp_page*p){if(!p)return;cp_page_header*h=cp_page_hdr(p);h->checksum=0;h->checksum=cp_crc32c(p->bytes,CP_PAGE_SIZE,0);}
cp_status cp_page_verify(const cp_page*p,uint64_t id){if(!p)return CP_E_RANGE;const cp_page_header*h=cp_page_chdr(p);if(h->magic!=CP_PAGE_MAGIC||h->version!=CP_PAGE_VERSION||h->page_id!=id||h->reserved!=0||h->type>CP_PAGE_BTREE_LEAF)return CP_E_CORRUPT;if(h->free_lower!=(uint16_t)(CP_PAGE_HEADER_SIZE+h->nslots*sizeof(cp_slot))||h->free_lower>h->free_upper||h->free_upper>CP_PAGE_SIZE)return CP_E_CORRUPT;uint32_t got=h->checksum;const size_t checksum_off=offsetof(cp_page_header,checksum);const uint32_t zero=0;uint32_t calculated=cp_crc32c(p->bytes,checksum_off,0);calculated=cp_crc32c(&zero,sizeof zero,calculated);calculated=cp_crc32c(p->bytes+checksum_off+sizeof zero,CP_PAGE_SIZE-checksum_off-sizeof zero,calculated);if(calculated!=got)return CP_E_CORRUPT;for(uint16_t i=0;i<h->nslots;i++){const cp_slot*s=(const cp_slot*)(p->bytes+CP_PAGE_HEADER_SIZE+(size_t)i*sizeof(cp_slot));if(s->len==0||s->off<h->free_upper||((uint32_t)s->off+s->len)>CP_PAGE_SIZE)return CP_E_CORRUPT;for(uint16_t j=0;j<i;j++){const cp_slot*t=(const cp_slot*)(p->bytes+CP_PAGE_HEADER_SIZE+(size_t)j*sizeof(cp_slot));if((uint32_t)s->off<t->off+t->len&&(uint32_t)t->off<s->off+s->len)return CP_E_CORRUPT;}}return CP_OK;}
void cp_page_init(cp_page*p,uint64_t id,cp_page_type type){if(!p)return;memset(p,0,sizeof(*p));cp_page_header*h=cp_page_hdr(p);h->magic=CP_PAGE_MAGIC;h->version=CP_PAGE_VERSION;h->type=(uint16_t)type;h->page_id=id;h->free_lower=CP_PAGE_HEADER_SIZE;h->free_upper=CP_PAGE_SIZE;}
uint16_t cp_page_free_space(const cp_page*p){const cp_page_header*h=cp_page_chdr(p);return h->free_upper>=h->free_lower?(uint16_t)(h->free_upper-h->free_lower):0;}
uint16_t cp_page_reclaimable_space(const cp_page*p){if(!p)return 0;uint32_t used=0;const cp_page_header*h=cp_page_chdr(p);if(h->nslots>(CP_PAGE_SIZE-CP_PAGE_HEADER_SIZE)/sizeof(cp_slot)||h->free_lower!=CP_PAGE_HEADER_SIZE+(uint32_t)h->nslots*sizeof(cp_slot)||h->free_upper<h->free_lower||h->free_upper>CP_PAGE_SIZE)return 0;for(uint16_t i=0;i<h->nslots;i++){const cp_slot*s=(const cp_slot*)(p->bytes+CP_PAGE_HEADER_SIZE+(size_t)i*sizeof(cp_slot));if(!s->len||s->off<h->free_upper||(uint32_t)s->off+s->len>CP_PAGE_SIZE)return 0;used+=s->len;if(used>(uint32_t)CP_PAGE_SIZE-h->free_lower)return 0;for(uint16_t j=0;j<i;j++){const cp_slot*t=(const cp_slot*)(p->bytes+CP_PAGE_HEADER_SIZE+(size_t)j*sizeof(cp_slot));if((uint32_t)s->off<t->off+t->len&&(uint32_t)t->off<s->off+s->len)return 0;}}uint32_t free=(uint32_t)CP_PAGE_SIZE-h->free_lower-used;return (uint16_t)(free>UINT16_MAX?UINT16_MAX:free);}
void cp_page_compact(cp_page*p){if(!p)return;cp_page_header*h=cp_page_hdr(p);if(cp_page_reclaimable_space(p)==0&&h->nslots!=0)return;uint8_t tmp[CP_PAGE_SIZE];uint16_t upper=CP_PAGE_SIZE;for(uint16_t i=0;i<h->nslots;i++){cp_slot*s=(cp_slot*)(p->bytes+CP_PAGE_HEADER_SIZE+(size_t)i*sizeof(cp_slot));upper=(uint16_t)(upper-s->len);memcpy(tmp+upper,p->bytes+s->off,s->len);s->off=upper;}memcpy(p->bytes+upper,tmp+upper,CP_PAGE_SIZE-upper);h->free_upper=upper;}
cp_status cp_page_insert_cell(cp_page*p,uint16_t idx,const void*cell,uint16_t len){if(!p||!cell||!len)return CP_E_RANGE;cp_page_header*h=cp_page_hdr(p);uint32_t needed=(uint32_t)sizeof(cp_slot)+len;if(h->nslots>(CP_PAGE_SIZE-CP_PAGE_HEADER_SIZE)/sizeof(cp_slot)||h->free_lower!=CP_PAGE_HEADER_SIZE+(uint32_t)h->nslots*sizeof(cp_slot)||h->free_upper<h->free_lower||h->free_upper>CP_PAGE_SIZE||idx>h->nslots||needed>CP_PAGE_SIZE-CP_PAGE_HEADER_SIZE)return CP_E_RANGE;if(cp_page_free_space(p)<needed){if(cp_page_reclaimable_space(p)<needed)return CP_E_RANGE;cp_page_compact(p);}memmove(p->bytes+CP_PAGE_HEADER_SIZE+(size_t)(idx+1)*sizeof(cp_slot),p->bytes+CP_PAGE_HEADER_SIZE+(size_t)idx*sizeof(cp_slot),(size_t)(h->nslots-idx)*sizeof(cp_slot));h->free_upper=(uint16_t)(h->free_upper-len);memcpy(p->bytes+h->free_upper,cell,len);cp_slot*s=(cp_slot*)(p->bytes+CP_PAGE_HEADER_SIZE+(size_t)idx*sizeof(cp_slot));s->off=h->free_upper;s->len=len;h->nslots++;h->free_lower=(uint16_t)(CP_PAGE_HEADER_SIZE+h->nslots*sizeof(cp_slot));return CP_OK;}
cp_status cp_page_delete_cell(cp_page*p,uint16_t idx){if(!p)return CP_E_RANGE;cp_page_header*h=cp_page_hdr(p);if(h->nslots>(CP_PAGE_SIZE-CP_PAGE_HEADER_SIZE)/sizeof(cp_slot)||h->free_lower!=CP_PAGE_HEADER_SIZE+(uint32_t)h->nslots*sizeof(cp_slot)||idx>=h->nslots)return CP_E_RANGE;memmove(p->bytes+CP_PAGE_HEADER_SIZE+(size_t)idx*sizeof(cp_slot),p->bytes+CP_PAGE_HEADER_SIZE+(size_t)(idx+1)*sizeof(cp_slot),(size_t)(h->nslots-idx-1)*sizeof(cp_slot));h->nslots--;h->free_lower=(uint16_t)(CP_PAGE_HEADER_SIZE+h->nslots*sizeof(cp_slot));return CP_OK;}
cp_status cp_page_get_cell(const cp_page*p,uint16_t idx,const void**cell,uint16_t*len){if(!p||!cell||!len)return CP_E_RANGE;const cp_page_header*h=cp_page_chdr(p);if(h->nslots>(CP_PAGE_SIZE-CP_PAGE_HEADER_SIZE)/sizeof(cp_slot)||h->free_lower!=CP_PAGE_HEADER_SIZE+(uint32_t)h->nslots*sizeof(cp_slot)||idx>=h->nslots)return CP_E_RANGE;const cp_slot*s=(const cp_slot*)(p->bytes+CP_PAGE_HEADER_SIZE+(size_t)idx*sizeof(cp_slot));if(!s->len||s->off<h->free_upper||h->free_upper>CP_PAGE_SIZE||(uint32_t)s->off+s->len>CP_PAGE_SIZE)return CP_E_CORRUPT;*cell=p->bytes+s->off;*len=s->len;return CP_OK;}
cp_status cp_page_read(cp_blockdev*d,uint64_t id,cp_page*out){if(!d||!out||id>UINT64_MAX/CP_PAGE_SIZE)return CP_E_RANGE;cp_status s=cp_dev_read(d,id*CP_PAGE_SIZE,out->bytes,CP_PAGE_SIZE);return s==CP_OK?cp_page_verify(out,id):s;}
cp_status cp_page_write(cp_blockdev*d,uint64_t id,cp_page*p){if(!d||!p||id>UINT64_MAX/CP_PAGE_SIZE)return CP_E_RANGE;cp_page_hdr(p)->page_id=id;cp_page_seal(p);return cp_dev_write(d,id*CP_PAGE_SIZE,p->bytes,CP_PAGE_SIZE);}
